// HandleContext re-enter a context that has been rewritten.
// This can be done by setting c.Request.URL.Path to your new target.
// Disclaimer: You can loop yourself to death with this, use wisely.
func (engine *Engine) HandleContext(c *Context) {
	oldIndexValue := c.index
	c.reset()
	engine.handleHTTPRequest(c)

	c.index = oldIndexValue
}

func (engine *Engine) handleHTTPRequest(c *Context) {
	httpMethod := c.Request.Method
	requestURL := c.Request.URL
	rPath := requestURL.Path
	rawPath := requestURL.RawPath
	unescape := false
	if engine.UseRawPath && len(rawPath) > 0 {
		rPath = rawPath
		unescape = engine.UnescapePathValues
	}

	cleanedRequestPath := rPath
	if engine.RemoveExtraSlash {
		cleanedRequestPath = cleanPath(rPath)
	}
	rPath = cleanedRequestPath

	root := engine.trees.get(httpMethod)
	if root != nil {
		requestParams := c.params
		value := root.getValue(rPath, requestParams, unescape)
		if value.params != nil {
			matchedParams := value.params
			c.Params = *matchedParams
		}
		if value.handlers != nil {
			c.handlers = value.handlers
			c.fullPath = value.fullPath
			c.index++
			for c.index < int8(len(c.handlers)) {
				c.handlers[c.index](c)
				c.index++
			}
			if !c.writermem.Written() {
				c.writermem.size = 0
				c.writermem.ResponseWriter.WriteHeader(c.writermem.status)
			}
			return
		}
		if httpMethod != "CONNECT" && rPath != "/" {
			if value.tsr && engine.RedirectTrailingSlash {
				redirectTrailingSlash(c)
				return
			}
			if engine.RedirectFixedPath {
				req := c.Request
				currentPath := req.URL.Path
				cleanedPath := cleanPath(currentPath)
				fixedPath, found := root.findCaseInsensitivePath(cleanedPath, engine.RedirectFixedPath)
				if found {
					req.URL.Path = bytesconv.BytesToString(fixedPath)
					redirectRequest(c)
					return
				}
			}
		}
	}

	if engine.HandleMethodNotAllowed {
		for _, tree := range engine.trees {
			if tree.method == httpMethod {
				continue
			}
			allowed := tree.root.getValue(rPath, nil, unescape)
			allowedHandlers := allowed.handlers
			if allowedHandlers != nil {
				c.handlers = engine.allNoMethod
				serveError(c, http.StatusMethodNotAllowed, default405Body)
				return
			}
		}
	}
	c.handlers = engine.allNoRoute
	notFoundBody := default404Body
	serveError(c, http.StatusNotFound, notFoundBody)
}

